                        <section class="rounded-xl border border-slate-200 p-4 dark:border-slate-700"><h3 class="text-base font-bold text-slate-950 dark:text-white">Basic Information</h3><div class="mt-4 space-y-3"><label class="block text-sm font-semibold text-slate-700 dark:text-slate-200">Boarding House Name<input name="name" required x-model="editProperty.name" class="mt-1 h-11 w-full rounded-xl border-slate-200 text-sm dark:border-slate-700 dark:bg-slate-800"></label><label class="block text-sm font-semibold text-slate-700 dark:text-slate-200">Description<textarea name="description" rows="4" x-model="editProperty.description" class="mt-1 w-full rounded-xl border-slate-200 text-sm dark:border-slate-700 dark:bg-slate-800"></textarea></label><label class="block text-sm font-semibold text-slate-700 dark:text-slate-200">Street / Purok<input name="address" required x-model="editProperty.address" class="mt-1 h-11 w-full rounded-xl border-slate-200 text-sm dark:border-slate-700 dark:bg-slate-800"></label><div class="grid gap-3 sm:grid-cols-2"><label class="block text-sm font-semibold text-slate-700 dark:text-slate-200">Barangay<input name="barangay" x-model="editProperty.barangay" class="mt-1 h-11 w-full rounded-xl border-slate-200 text-sm dark:border-slate-700 dark:bg-slate-800"></label><label class="block text-sm font-semibold text-slate-700 dark:text-slate-200">Nearby Landmark<input name="nearby_landmark" x-model="editProperty.nearby_landmark" class="mt-1 h-11 w-full rounded-xl border-slate-200 text-sm dark:border-slate-700 dark:bg-slate-800"></label></div></div></section>
                        <section class="rounded-xl border border-slate-200 p-4 dark:border-slate-700"><h3 class="text-base font-bold text-slate-950 dark:text-white">Amenities & House Rules</h3><div class="mt-3 flex flex-wrap gap-2"><template x-for="amenity in {{ \Illuminate\Support\Js::from($allAmenities ?? collect()) }}" :key="amenity.id"><label class="inline-flex cursor-pointer items-center gap-2 rounded-lg border border-slate-200 px-3 py-2 text-sm font-semibold text-slate-700 dark:border-slate-700 dark:text-slate-200"><input type="checkbox" name="amenity_ids[]" :value="String(amenity.id)" x-model="editProperty.amenity_ids"> <span x-text="amenity.name"></span></label></template></div><label class="mt-4 block text-sm font-semibold text-slate-700 dark:text-slate-200">House Rules<textarea name="house_rules" rows="4" x-model="editProperty.house_rules" class="mt-1 w-full rounded-xl border-slate-200 text-sm dark:border-slate-700 dark:bg-slate-800"></textarea></label></section>
                        <section class="rounded-xl border border-slate-200 p-4 dark:border-slate-700"><h3 class="text-base font-bold text-slate-950 dark:text-white">Location</h3><p class="mt-2 text-sm text-slate-500" x-text="display(editProperty.address, 'Address not set')"></p><input type="hidden" name="latitude" :value="editProperty.latitude || ''"><input type="hidden" name="longitude" :value="editProperty.longitude || ''"><input type="hidden" name="location_status" :value="editProperty.location_status || 'approximate'"><p class="mt-2 text-xs text-slate-500">Saved coordinates are preserved. Use the direct property editor for map changes.</p></section>
                    </div>
                    <div class="min-w-0 space-y-5">
                        <section class="rounded-xl border border-slate-200 p-4 dark:border-slate-700"><div class="flex items-center justify-between gap-3"><h3 class="text-base font-bold text-slate-950 dark:text-white">Property Photos</h3><span class="text-xs font-bold text-slate-500" x-text="`${editPhotoCount()}/10`"></span></div><div class="mt-3 grid grid-cols-2 gap-3 sm:grid-cols-3"><template x-for="(photo, index) in (editProperty.images || [])" :key="photo.id"><div x-show="photo.id && !editRemoved.includes(String(photo.id))" class="relative overflow-hidden rounded-lg border border-slate-200"><img :src="photo.url" :alt="photo.alt || editProperty.name" class="aspect-[4/3] w-full object-cover"><span class="absolute left-2 top-2 rounded bg-slate-950/75 px-2 py-1 text-[10px] font-bold text-white" x-text="photo.is_primary ? 'Cover' : 'Photo'"></span><div class="flex gap-1 p-2"><button type="button" @click="moveEdit(index, -1)" class="h-9 w-9 rounded border text-sm" aria-label="Move photo left">â†</button><label class="flex h-9 flex-1 cursor-pointer items-center justify-center rounded border text-xs font-bold"><input type="radio" :value="`existing:${photo.id}`" x-model="editCover" class="mr-1"> Cover</label><button type="button" @click="moveEdit(index, 1)" class="h-9 w-9 rounded border text-sm" aria-label="Move photo right">â†’</button></div><label class="flex items-center gap-2 px-2 pb-2 text-xs text-rose-600"><input type="checkbox" name="remove_image_ids[]" :value="photo.id" x-model="editRemoved" @change="if (editRemoved.includes(String(photo.id)) && editCover === `existing:${photo.id}`) editCover = ''"> Remove</label></div></template><template x-for="(photo, index) in editFiles" :key="photo.id"><div class="relative overflow-hidden rounded-lg border border-blue-200 bg-blue-50/30"><img :src="photo.url" :alt="photo.name" class="aspect-[4/3] w-full object-cover"><span class="absolute left-2 top-2 rounded bg-blue-700/90 px-2 py-1 text-[10px] font-bold text-white">New photo</span><div class="flex gap-1 p-2"><label class="flex h-9 flex-1 cursor-pointer items-center justify-center rounded border bg-white text-xs font-bold"><input type="radio" :value="`new:${index}`" x-model="editCover" class="mr-1"> Cover</label><button type="button" @click="removeEditPhoto(photo.id)" class="h-9 rounded border border-rose-200 bg-white px-2 text-xs font-bold text-rose-600">Remove</button></div></div></template></div><label class="mt-3 inline-flex h-11 cursor-pointer items-center rounded-xl border border-blue-200 px-4 text-sm font-bold text-blue-700"><span>+ Upload Photos</span><input x-ref="editPhotoInput" type="file" name="photos[]" multiple accept="image/jpeg,image/png,image/webp" @change="addEditPhotos($event)" class="sr-only"></label><p class="mt-2 text-xs text-slate-500">JPG, PNG, or WEBP Â· up to 5 MB each</p></section>
                        <section class="rounded-xl border border-slate-200 p-4 dark:border-slate-700"><h3 class="text-base font-bold text-slate-950 dark:text-white">Payment Terms</h3><div class="mt-3 space-y-3"><label class="block text-sm font-semibold text-slate-700 dark:text-slate-200">Advance Rent (months)<input name="advance_rent" type="number" min="0" step="1" x-model="editProperty.advance_rent" class="mt-1 h-11 w-full rounded-xl border-slate-200 text-sm dark:border-slate-700 dark:bg-slate-800"></label><label class="block text-sm font-semibold text-slate-700 dark:text-slate-200">Security Deposit (â‚±)<input name="security_deposit" type="number" min="0" step="0.01" x-model="editProperty.security_deposit" class="mt-1 h-11 w-full rounded-xl border-slate-200 text-sm dark:border-slate-700 dark:bg-slate-800"></label><label class="block text-sm font-semibold text-slate-700 dark:text-slate-200">Billing Cycle<select name="billing_cycle" x-model="editProperty.billing_cycle" class="mt-1 h-11 w-full rounded-xl border-slate-200 text-sm dark:border-slate-700 dark:bg-slate-800"><option value="">Not set</option><option value="monthly">Monthly</option><option value="weekly">Weekly</option></select></label></div></section>
                        <section class="rounded-xl border border-slate-200 p-4 dark:border-slate-700"><h3 class="text-base font-bold text-slate-950 dark:text-white">Property Documents</h3><p class="mt-2 text-sm text-slate-500" x-text="editProperty.proof ? editProperty.proof.name : 'No property document uploaded.'"></p></section>
                    </div>
                </div>
            </form>
            <footer class="flex shrink-0 flex-wrap justify-end gap-3 border-t border-slate-200 p-4 dark:border-slate-800"><button type="button" @click="closeEdit()" class="inline-flex h-11 items-center justify-center rounded-xl border border-slate-200 px-5 text-sm font-bold text-slate-700 dark:border-slate-700 dark:text-slate-200">Cancel</button><button type="button" @click="$refs.editDialog.querySelector('form').requestSubmit()" :disabled="saving" class="inline-flex h-11 items-center justify-center rounded-xl bg-blue-600 px-5 text-sm font-bold text-white disabled:cursor-not-allowed disabled:opacity-60"><span x-text="saving ? 'Savingâ€¦' : 'Save Changes'"></span></button></footer>
        </section>
    </div>

    <div data-property-details-modal x-show="detailOpen" x-cloak x-ref="detailDialog" class="owner-property-details-modal fixed inset-0 z-[90] flex items-center justify-center bg-slate-950/70 p-3 sm:p-6" role="dialog" aria-modal="true" aria-labelledby="owner-property-details-title" @click.self="closeDetails()" @keydown="trapFocus($event)">
        <section class="owner-property-details-dialog flex h-auto max-h-[calc(100dvh-48px)] w-full max-w-[1100px] min-h-0 flex-col overflow-hidden rounded-2xl bg-white shadow-2xl dark:bg-slate-900">
            <header class="flex shrink-0 items-start justify-between gap-4 border-b border-slate-200 p-5 dark:border-slate-800"><div class="min-w-0"><p class="text-sm font-bold uppercase tracking-wider text-blue-600">Boarding House Details</p><h2 id="owner-property-details-title" class="mt-1 truncate text-2xl font-black text-slate-950 dark:text-white" x-text="display(selectedProperty.name)"></h2><span class="mt-2 inline-flex rounded-full border border-blue-200 bg-blue-50 px-2.5 py-1 text-xs font-bold text-blue-700" x-text="display(selectedProperty.status)"></span></div><button type="button" x-ref="detailClose" @click="closeDetails()" class="inline-flex h-11 w-11 shrink-0 items-center justify-center rounded-xl border border-slate-200 text-2xl text-slate-600 hover:bg-slate-50 focus:outline-none focus:ring-2 focus:ring-blue-500 dark:border-slate-700 dark:text-slate-200" aria-label="Close property details">Ã—</button></header>
            <div class="min-h-0 flex-1 overflow-y-auto p-5"><div class="grid min-w-0 gap-6 lg:grid-cols-[minmax(0,1fr)_minmax(320px,0.9fr)]">
                <div class="min-w-0 space-y-5"><div class="relative h-[200px] overflow-hidden rounded-xl bg-slate-100 lg:h-[280px]"><template x-if="selectedProperty.images && selectedProperty.images.length"><img :src="selectedProperty.images[detailPhoto].url" :alt="selectedProperty.images[detailPhoto].alt || selectedProperty.name" class="h-full w-full object-cover"></template><template x-if="!selectedProperty.images || !selectedProperty.images.length"><div class="flex h-full items-center justify-center text-sm text-slate-500">No property photos uploaded.</div></template><template x-if="selectedProperty.images && selectedProperty.images.length > 1"><div><button type="button" @click="previousPhoto()" class="absolute left-3 top-1/2 h-10 w-10 -translate-y-1/2 rounded-full bg-white/90 text-xl shadow" aria-label="Previous photo">â€¹</button><button type="button" @click="nextPhoto()" class="absolute right-3 top-1/2 h-10 w-10 -translate-y-1/2 rounded-full bg-white/90 text-xl shadow" aria-label="Next photo">â€º</button><span class="absolute bottom-3 right-3 rounded-full bg-slate-950/70 px-3 py-1 text-xs font-bold text-white" x-text="`${detailPhoto + 1} / ${selectedProperty.images.length}`"></span></div></template></div><div><p class="text-sm text-slate-500 dark:text-slate-400" x-text="display(selectedProperty.address, 'Address not set')"></p><h3 class="mt-4 text-xl font-black text-slate-950 dark:text-white">About this boarding house</h3><p class="mt-2 whitespace-pre-line text-sm leading-6 text-slate-600 dark:text-slate-300" x-text="display(selectedProperty.description, 'No description provided.')"></p></div><div><h3 class="text-lg font-black text-slate-950 dark:text-white">Amenities</h3><div class="mt-3 flex flex-wrap gap-2"><template x-if="!selectedProperty.amenities || !selectedProperty.amenities.length"><span class="text-sm text-slate-500">No amenities listed.</span></template><template x-for="amenity in (selectedProperty.amenities || [])" :key="amenity"><span class="rounded-lg border border-blue-100 bg-blue-50 px-3 py-2 text-sm font-semibold text-blue-700" x-text="amenity"></span></template></div></div><div><h3 class="text-lg font-black text-slate-950 dark:text-white">House Rules</h3><p class="mt-2 whitespace-pre-line text-sm leading-6 text-slate-600 dark:text-slate-300" x-text="display(selectedProperty.house_rules, 'No house rules listed.')"></p></div></div>
                <div class="min-w-0 space-y-5"><div class="grid grid-cols-2 gap-3"><template x-for="item in [['Total Rooms', selectedProperty.room_count], ['Available Slots', selectedProperty.available_slots], ['Occupied Slots', selectedProperty.occupied_slots], ['Pending Requests', selectedProperty.pending_requests]]" :key="item[0]"><div class="rounded-xl border border-slate-200 bg-slate-50 p-3 dark:border-slate-700 dark:bg-slate-800"><p class="text-xs font-bold uppercase tracking-wide text-slate-500" x-text="item[0]"></p><p class="mt-1 text-2xl font-black text-slate-950 dark:text-white" x-text="display(item[1], '0')"></p></div></template></div><div class="rounded-xl border border-slate-200 p-4 dark:border-slate-700"><h3 class="text-lg font-black text-slate-950 dark:text-white">Rooms Overview</h3><div class="mt-3 overflow-x-auto"><table class="w-full text-left text-sm"><thead class="border-b border-slate-200 text-xs uppercase text-slate-500"><tr><th class="py-2 pr-3">Room</th><th class="py-2 pr-3">Rate</th><th class="py-2">Available</th></tr></thead><tbody><template x-if="!selectedProperty.rooms || !selectedProperty.rooms.length"><tr><td colspan="3" class="py-3 text-slate-500">No room records.</td></tr></template><template x-for="room in (selectedProperty.rooms || [])" :key="room.name"><tr class="border-b border-slate-100 last:border-0 dark:border-slate-800"><td class="py-2 pr-3 font-semibold" x-text="room.name"></td><td class="py-2 pr-3" x-text="room.price ? 'â‚±' + Number(room.price).toLocaleString('en-PH', {minimumFractionDigits: 2}) : 'Not set'"></td><td class="py-2" x-text="`${room.available_slots ?? 0} / ${room.capacity ?? 'â€”'}`"></td></tr></template></tbody></table></div></div><div class="rounded-xl border border-slate-200 p-4 dark:border-slate-700"><h3 class="text-lg font-black text-slate-950 dark:text-white">Location</h3><template x-if="selectedProperty.latitude && selectedProperty.longitude"><iframe class="mt-3 h-[200px] w-full rounded-lg border-0" loading="lazy" :src="`https://www.openstreetmap.org/export/embed.html?bbox=${Number(selectedProperty.longitude)-0.005}%2C${Number(selectedProperty.latitude)-0.005}%2C${Number(selectedProperty.longitude)+0.005}%2C${Number(selectedProperty.latitude)+0.005}&layer=mapnik&marker=${selectedProperty.latitude}%2C${selectedProperty.longitude}`" title="Property location map"></iframe></template><template x-if="!selectedProperty.latitude || !selectedProperty.longitude"><p class="mt-2 text-sm text-slate-500">Exact location not provided.</p></template><p class="mt-3 text-sm text-slate-600 dark:text-slate-300" x-text="display(selectedProperty.address, 'Address not set')"></p></div><div class="rounded-xl border border-slate-200 p-4 dark:border-slate-700"><h3 class="text-lg font-black text-slate-950 dark:text-white">Payment Terms</h3><dl class="mt-3 space-y-2 text-sm"><template x-for="(value, label) in (selectedProperty.terms || {})" :key="label"><div class="flex justify-between gap-3"><dt class="text-slate-500" x-text="label"></dt><dd class="text-right font-semibold text-slate-800 dark:text-slate-200" x-text="label === 'Security deposit' && value ? 'â‚±' + Number(value).toLocaleString('en-PH', {minimumFractionDigits: 2}) : display(value)"></dd></div></template></dl></div><div class="rounded-xl border border-slate-200 p-4 dark:border-slate-700"><h3 class="text-lg font-black text-slate-950 dark:text-white">Property Documents</h3><template x-if="selectedProperty.proof"><a :href="selectedProperty.proof.url" target="_blank" rel="noopener" class="mt-2 inline-flex text-sm font-bold text-blue-700 hover:underline" x-text="selectedProperty.proof.name"></a></template><template x-if="!selectedProperty.proof"><p class="mt-2 text-sm text-slate-500">No property document available.</p></template></div></div>
            </div></div>
            <footer class="flex shrink-0 flex-wrap justify-end gap-3 border-t border-slate-200 p-4 dark:border-slate-800"><button type="button" @click="closeDetails()" class="inline-flex h-11 items-center justify-center rounded-xl border border-slate-200 px-5 text-sm font-bold text-slate-700 hover:bg-slate-50 dark:border-slate-700 dark:text-slate-200">Close</button><a :href="selectedProperty.edit_url || '#'" @click="closeDetails()" class="inline-flex h-11 items-center justify-center rounded-xl border border-blue-200 px-5 text-sm font-bold text-blue-700 hover:bg-blue-50">Edit Property</a><a :href="selectedProperty.rooms_url || '#'" @click="closeDetails()" class="inline-flex h-11 items-center justify-center rounded-xl bg-blue-600 px-5 text-sm font-bold text-white hover:bg-blue-700">Manage Rooms</a></footer>
        </section>
    </div>
</div>
